Title: Unexpected WRP0 Value When Disabling Write Protection on STM32F103C6

Body:
## How to enable/disable FLASH WRP

> - **Device**: STM32F103C6Tx  
> - **Firmware Package**: STM32Cube FW_F1 v1.8.6 (latest)  
> - **Toolchain**: GCC  

When using HAL_FLASHEx_OBProgram() to **disable** write protection (WRP) on
specific pages, the resulting Option Byte value is unexpected.

### Code and Log

1. On power-up, all flash pages are **not** write-protected.
2. After enabling WRP on pages 0–31, WRP0 becomes 0x00.
3. After **disabling** WRP on pages 0–3, WRP0 becomes 0xFF(expected 0x01)

c
void print_option_bytes(void)
{
  __IO uint8_t *ob = (__IO uint8_t *)OB_BASE;
  __IO uint8_t *ob_end = (__IO uint8_t *)(OB_BASE + 16);
  printf("ob(%p): ", ob);
  while (ob < ob_end) {
    printf("%02x ", *ob++);
  }
  printf("\b\r\n");
}

void flash_write_wrp(uint8_t wrp_enable, uint32_t wrp)
{
  FLASH_OBProgramInitTypeDef flash_ob;
  flash_ob.OptionType = OPTIONBYTE_WRP;
  flash_ob.WRPState = wrp_enable ? OB_WRPSTATE_ENABLE : OB_WRPSTATE_DISABLE;
  flash_ob.WRPPage = wrp;

  HAL_FLASH_Unlock();
  HAL_FLASH_OB_Unlock();

  HAL_StatusTypeDef result = HAL_FLASHEx_OBProgram(&flash_ob);

  HAL_FLASH_OB_Lock();
  HAL_FLASH_Lock();

  printf("flash_write_wrp ret: %d\r\n", result);
  print_option_bytes();

  HAL_FLASH_OB_Launch();
}

int main(void)
{
  HAL_Init();
  SystemClock_Config();

  MX_GPIO_Init();
  MX_USART2_UART_Init();

  // -- User Code
  printf("system start\r\n");
  print_option_bytes();

  uint8_t ch = 0;
  while (1) {
    if (HAL_UART_Receive(&huart2, &ch, 1, HAL_MAX_DELAY) != HAL_OK) {
      continue;
    }
    printf("\n recv ch: %c(%x)\r\n", ch, ch);
    if (ch == 'w') {
      flash_write_wrp(1, OB_WRP_PAGES0TO31MASK); // protect 0~31
    } else {
      flash_write_wrp(0, OB_WRP_PAGES0TO3); // disable 0~3
    }
  }

  return 0;
}


txt
system start                                                      # mcu power on
ob(0x1ffff800): a5 5a ff ff ff ff ff ff ff 00 ff ff ff ff ff ff

w                                                                 # pc send 'w'
 recv ch: w(77)                                                   # mcu recv 'w'
flash_write_wrp ret: 0                                            # enable protect 0~31 pages success
ob(0x1ffff800): a5 5a ff ff ff ff ff ff 00 ff ff ff ff ff ff ff   # ok: wpr0 is 0x00
system start                                                      # after HAL_FLASH_OB_Launch
ob(0x1ffff800): a5 5a ff ff ff ff ff ff 00 ff ff ff ff ff ff ff

W                                                                 # pc send 'W'
 recv ch: W(57)                                                   # mcu recv 'W'
flash_write_wrp ret: 0                                            # disable protect 0~3 pages success
ob(0x1ffff800): a5 5a ff ff ff ff ff ff ff 00 ff ff ff ff ff ff   # ?: expected 0x01
system start                                                      # after HAL_FLASH_OB_Launch
ob(0x1ffff800): a5 5a ff ff ff ff ff ff ff 00 ff ff ff ff ff ff


### Try analysis

The following code is FLASH_OB_DisableWRP in STM32F103x6(remove unused code)

1. If WriteProtectPage is 0x01
  - WriteProtectPage: will be 0x00 | 0x01 = 0x01
  - WRP0_Data: will be 0x01 & 0xFF = 0x01
2. After HAL_FLASHEx_OBErase();: OB->WRP0 is 0xFF,
3. After OB->WRP0 |= WRP0_Data;: is OB->WRP0 is 0xFF | 0x01 = 0xFF

Is this a bug in the HAL library or a problem caused by incorrect usage on my part?


c
static HAL_StatusTypeDef FLASH_OB_DisableWRP(uint32_t WriteProtectPage)
{
  HAL_StatusTypeDef status = HAL_OK;
  uint16_t WRP0_Data = 0xFFFF;

  /* Check the parameters */
  assert_param(IS_OB_WRP(WriteProtectPage));

  /* Get current write protected pages and the new pages to be unprotected ******/
  WriteProtectPage = (FLASH_OB_GetWRP() | WriteProtectPage);

  WRP0_Data = (uint16_t)(WriteProtectPage & OB_WRP_PAGES0TO31MASK);

  /* Wait for last operation to be completed */
  status = FLASH_WaitForLastOperation((uint32_t)FLASH_TIMEOUT_VALUE);

  if(status == HAL_OK)
  { 
    /* Clean the error context */
    pFlash.ErrorCode = HAL_FLASH_ERROR_NONE;

    /* To be able to write again option byte, need to perform a option byte erase */
    status = HAL_FLASHEx_OBErase();
    if (status == HAL_OK)  
    {
      SET_BIT(FLASH->CR, FLASH_CR_OPTPG);

      if(WRP0_Data != 0xFFU)
      {
        OB->WRP0 |= WRP0_Data;

        /* Wait for last operation to be completed */
        status = FLASH_WaitForLastOperation((uint32_t)FLASH_TIMEOUT_VALUE);
      }

      /* if the program operation is completed, disable the OPTPG Bit */
      CLEAR_BIT(FLASH->CR, FLASH_CR_OPTPG);
    }
  }
  return status;
}

